package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type Pair struct {
	One int
	Two int
}

func aux(n int) int{
	if n < 0{
		return -n
	}
	return n
}

func occurr(vet []int) []Pair {
	if len(vet) == 0{
		return nil
	}
	cont := make(map[int]int)
	for _, v := range vet {
		cont[aux(v)]++
	}

	var keys []int
	for k := range cont {
		keys = append(keys, k)
	}
	sort.Ints(keys)

	var r []Pair
	for _, k := range keys {
		r = append(r, Pair{k, cont[k]})
	}
	return r
}

func teams(vet []int) []Pair {
	if len(vet) == 0{
		return nil
	}

	var r []Pair
	currentS := aux(vet[0])
	cont := 1
	for i := 1; i < len(vet); i++ {
		s := aux(vet[i])
		if s == currentS {
			cont++
		} else {
			r = append(r, Pair{currentS, cont})
			currentS = s
			cont = 1
		}
	}
	r = append(r, Pair{currentS, cont})
	return r
}

func mnext(vet []int) []int {
	r := make([]int, len(vet))
	for i := 0; i < len(vet); i++ {
		if vet[i] > 0{
			vizM := false
			if i > 0 && vet[i - 1] < 0{
				vizM = true
			}
			if i < len(vet) - 1 && vet[i + 1] < 0{
				vizM = true
			}
			if vizM {
				r[i] = 1
			}
		}
	}
	return r
}

func alone(vet []int) []int {
	r := make([]int, len(vet))
	for i := 0; i < len(vet); i++ {
		if vet[i] > 0{
			vizM := false
			if i > 0 && vet[i - 1] < 0{
				vizM = true
			}
			if i < len(vet) - 1 && vet[i + 1] < 0{
				vizM = true
			}
			if !vizM {
				r[i] = 1
			}
		}
	}
	return r
}

func couple(vet []int) int {
	h := make(map [int]int)
	m := make(map [int]int)

	for _, x := range vet{
		if x > 0{
			h[x]++
		} else if x < 0{
			m[-x]++
		}
	}

	casais := 0
	for s, hCont := range h{
		mCont := m[s]
		if hCont < mCont{
			casais += hCont
		} else {
			casais += mCont
		}
	}
	return casais
}

func hasSubseq(vet []int, seq []int, pos int) bool {
	if pos+len(seq) > len(vet){
		return false
	}
	for i := 0; i < len(seq); i++{
		if vet[pos+i] != seq[i]{
			return false
		}
	}
	return true
}

func subseq(vet []int, seq []int) int {
	if len(seq) == 0{
		return 0
	}
	for i:= 0; i <= len(vet) - len(seq); i++{
		if hasSubseq(vet, seq, i){
			return i
		}
	}
	return -1
}

func erase(vet []int, posList []int) []int {
	remover := make(map[int]bool)
	for _, pos := range posList{
		remover[pos] = true
	}

	var r []int
	for i, val := range vet {
		if !remover[i]{
			r = append(r, val)
		}
	}
	return r
}

func clear(vet []int, value int) []int {
	var r []int
	for _, val := range vet {
		if val != value{
			r = append(r, val)
		}
	}
	return r
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	for {
		fmt.Print("$")
		if !scanner.Scan() {
			break
		}
		line := scanner.Text()
		args := strings.Split(line, " ")
		fmt.Println(line)

		switch args[0] {
		case "occurr":
			printSlice(occurr(str2vet(args[1])))
		case "teams":
			printSlice(teams(str2vet(args[1])))
		case "mnext":
			printSlice(mnext(str2vet(args[1])))
		case "alone":
			printSlice(alone(str2vet(args[1])))
		case "erase":
			printSlice(erase(str2vet(args[1]), str2vet(args[2])))
		case "clear":
			val, _ := strconv.Atoi(args[2])
			printSlice(clear(str2vet(args[1]), val))
		case "subseq":
			fmt.Println(subseq(str2vet(args[1]), str2vet(args[2])))
		case "couple":
			fmt.Println(couple(str2vet(args[1])))
		case "end":
			return
		default:
			fmt.Println("Invalid command")
		}
	}
}

// Funções auxiliares

func str2vet(str string) []int {
	if str == "[]" {
		return nil
	}
	str = str[1 : len(str)-1]
	parts := strings.Split(str, ",")
	var vet []int
	for _, part := range parts {
		num, _ := strconv.Atoi(strings.TrimSpace(part))
		vet = append(vet, num)
	}
	return vet
}

func printSlice[T any](vet []T) {
	fmt.Print("[")
	for i, x := range vet {
		if i > 0 {
			fmt.Print(", ")
		}
		fmt.Print(x)
	}
	fmt.Println("]")
}

func (p Pair) String() string {
	return fmt.Sprintf("(%v, %v)", p.One, p.Two)
}
